ask=["Personal details and contact","Secondary education (SSC/O-Level and HSC/A-Level)","Bachelor's degree (if applicable)","Master's degree (if applicable)","PhD and research profile (if applicable)","Language and admission tests (only those you have)","Preferred degree, countries, field and intake","Documents: CV, transcripts, SOP (optional)","Goals, questions and consent"]
W["assessment.html"]=page("assessment.html","Profile Assessment | ScholarFly BD","Submit your academic profile for an initial ScholarFly BD assessment through a private Google Form.",top("Profile assessment","Tell us about your academic background and goals. The initial assessment is free.")+f'''<section class="sec"><div class="wrap two"><div><h2>What the form asks</h2><ul class="checks">{"".join(f"<li>{a}</li>" for a in ask)}</ul><p class="muted">Sections that do not apply to you are skipped. Do not upload passports, national IDs or financial documents. CV upload through Google Forms may need a Google sign-in.</p><h2>What happens next</h2><p>Your response goes to a private Google Sheet. We review it, and you receive feedback by email. Your data is never shown publicly. Read our <a href="privacy.html">Privacy Policy</a>.</p></div><div><div class="card" id="form-ready" hidden><h3>Start your assessment</h3><a class="btn gold" id="form-btn" target="_blank" rel="noopener noreferrer" href="#">Open the assessment form</a></div><div class="card" id="form-pending"><h3>Form opening soon</h3><p>The assessment form is not yet connected, so please do not expect a submission to be received. To start now, email <a href="mailto:scholarflybd@gmail.com?subject=Profile%20assessment">scholarflybd@gmail.com</a> and we will reply with next steps.</p></div></div></div></section><section class="sec tint" id="form-embed" hidden><div class="wrap"><iframe id="form-frame" title="ScholarFly BD profile assessment form" loading="lazy" height="1400"></iframe></div></section>''')
# PRIVACY / TERMS
W["privacy.html"]=page("privacy.html","Privacy Policy | ScholarFly BD","How ScholarFly BD handles information submitted for profile assessment.",top("Privacy Policy","Draft for owner review. Last updated: "+datetime.date.today().strftime("%B %Y"))+'''<section class="sec"><div class="wrap prose"><h2>What we collect</h2><p>Through the assessment form: name, contact details, education history, test scores, research experience, study preferences and optional documents such as a CV.</p><h2>How we use it</h2><p>To assess your profile, contact you and prepare feedback. Optional updates about scholarships are sent only if you agree separately.</p><h2>Storage and access</h2><p>Responses are stored in Google Forms, Google Sheets and Google Drive, accessible only to authorised ScholarFly BD reviewers. We do not publish or sell your information.</p><h2>What we do not want</h2><p>Please do not submit passport or national ID copies or financial documents.</p><h2>Retention</h2><p>We keep assessment records only as long as needed to provide feedback and follow-up, then delete them on request or on a schedule set by the owner.</p><h2>Your rights</h2><p>To access, correct or delete your information, email <a href="mailto:scholarflybd@gmail.com">scholarflybd@gmail.com</a>.</p><p class="notice">This notice is a draft. The owner must confirm the retention period and review it against applicable privacy law before collecting applications.</p></div></section>''')
W["terms.html"]=page("terms.html","Terms & Conditions | ScholarFly BD","Terms for using the ScholarFly BD website and guidance.",top("Terms &amp; Conditions","Draft for owner review.")+'''<section class="sec"><div class="wrap prose"><h2>Informational use</h2><p>Content on this website is for general guidance only. Scholarship details can change; confirm everything with the official provider.</p><h2>No guarantees</h2><p>ScholarFly BD does not guarantee admission, scholarships, supervisor responses or visas.</p><h2>No affiliation</h2><p>We are independent and are not affiliated with any university, government or scholarship provider named on this site.</p><h2>Your information</h2><p>You confirm that information you submit is accurate. See the <a href="privacy.html">Privacy Policy</a>.</p><h2>Paid services</h2><p>Any paid service will be agreed in writing with its scope and fee before it begins.</p><h2>External links</h2><p>We are not responsible for content on third-party websites.</p><p class="notice">This is a draft and should be reviewed by a qualified adviser before launch.</p></div></section>''')
# SCHOLARSHIPS
opt=lambda l:"".join(f'<option value="{v}">{t}</option>' for v,t in l)
W["scholarships.html"]=page("scholarships.html","Scholarship Directory | ScholarFly BD","Search scholarship pathways in 30 study destinations by country, degree, funding type and coverage.",top("Scholarship directory","30 study destinations and the established programmes worth researching.")+f'''<section class="sec"><div class="wrap"><div class="notice">Entries are pathways to research, not confirmed open awards. Deadlines, eligibility and benefits are marked "pending" until verified against the official site.</div><form class="filters" role="search" onsubmit="return false"><label>Search<input id="q" type="search" placeholder="Country, scholarship or provider"></label><label>Country<select id="fc"><option value="">All</option>{opt([(x["iso"],x["name"]) for x in data])}</select></label><label>Region<select id="fr"><option value="">All</option>{opt([(r,r) for r in sorted({x["region"] for x in data})])}</select></label><label>Degree<select id="fd"><option value="">All</option>{opt(LV.items())}</select></label><label>Funding type<select id="ft"><option value="">All</option>{opt([(t,t) for t in ("Government","University","Research","External")])}</select></label><label>Coverage<select id="fv"><option value="">All</option>{opt([(t,t) for t in ("Full","Partial","Varies")])}</select></label><button type="reset" class="btn">Clear</button></form><p id="count" aria-live="polite"></p><div id="grid" class="grid3"></div></div></section><dialog id="dlg" aria-labelledby="dt"><button class="close" aria-label="Close">Close</button><div id="dbody"></div></dialog>''')
for f,h in W.items(): open(f,"w").write(h)
open("sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f'<url><loc>{D if f=="index.html" else D+f}</loc></url>' for f in W)+'</urlset>')
open("robots.txt","w").write("User-agent: *\nAllow: /\nSitemap: https://scholarflybd.com/sitemap.xml\n")
